static int st_is_finite_quat(const adcs_quat_t *q) {
    return (q != NULL) && isfinite(q->w) && isfinite(q->x) && isfinite(q->y) && isfinite(q->z);
}

static void st_set_fault(void) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    st_output.innovation_rad = 0.0;
    st_output.axis.x = 0.0;
    st_output.axis.y = 0.0;
    st_output.axis.z = 0.0;
    st_output.rejects = st_state.rejects;
}

void GncRepoSTHysteresisStep(void) {
    adcs_quat_t qp, qm, qerr;
    adcs_vec3_t v, axis;
    double s, angle;

    if (st_state.mode == ST_FAULT) {
        st_set_fault();
        return;
    }

    if (st_input.enable != 0 && st_input.enable != 1) {
        st_set_fault();
        return;
    }
    if (!isfinite(st_config.accept_rad) || !isfinite(st_config.reject_rad) ||
        st_config.accept_rad < 0.0 || st_config.accept_rad >= st_config.reject_rad ||
        st_config.reject_rad > ADCS_PI || st_config.max_rejects < 1U || st_config.max_rejects > 20U) {
        st_set_fault();
        return;
    }
    if (st_input.predicted == NULL || st_input.measured == NULL) {
        st_set_fault();
        return;
    }
    if (!st_is_finite_quat(st_input.predicted) || !st_is_finite_quat(st_input.measured)) {
        st_set_fault();
        return;
    }
    if (adcs_quat_normalize(st_input.predicted, &qp) != ADCS_OK ||
        adcs_quat_normalize(st_input.measured, &qm) != ADCS_OK) {
        st_set_fault();
        return;
    }

    if (st_input.enable == 0) {
        st_state.mode = ST_ACCEPT;
        st_state.rejects = 0U;
        st_output.mode = ST_ACCEPT;
        st_output.rejects = 0U;
        st_output.innovation_rad = 0.0;
        st_output.axis.x = 0.0;
        st_output.axis.y = 0.0;
        st_output.axis.z = 0.0;
        return;
    }

    qerr = adcs_quat_multiply(&qm, &adcs_quat_conjugate(&qp));
    s = adcs_quat_abs_dot(&qm, &qp);
    if (s > 1.0) {
        s = 1.0;
    }
    angle = 2.0 * acos(s);

    v.x = qerr.x;
    v.y = qerr.y;
    v.z = qerr.z;
    if (adcs_vec3_normalize(&v, ADCS_EPS_NORM, &axis) != ADCS_OK) {
        axis.x = 0.0;
        axis.y = 0.0;
        axis.z = 0.0;
    }

    st_output.innovation_rad = angle;
    st_output.axis = axis;

    if (angle <= st_config.accept_rad) {
        st_state.mode = ST_ACCEPT;
        st_state.rejects = 0U;
    } else if (angle < st_config.reject_rad) {
        /* preserve prior decision and count */
    } else {
        if (st_state.rejects < st_config.max_rejects) {
            st_state.rejects += 1U;
        }
        if (st_state.rejects >= st_config.max_rejects) {
            st_state.mode = ST_FAULT;
        } else {
            st_state.mode = ST_REJECT;
        }
    }

    st_output.mode = st_state.mode;
    st_output.rejects = st_state.rejects;
}

